// src/csound/CsoundGenerator.js
import { libraryStore } from '../api/index.js';
const BASE_UDOS = ['led_rms.txt', 'mVU_rms.txt'];
export class CsoundGenerator {
    constructor() {
        // Множество инклудов (typeId)
        this.includes = new Set();
        
        // Активные модули с их данными
        this.modules = new Map(); // key: instanceId, value: moduleData
        
        // Счётчики шин для zakinit
        this._audioBusCount = 2;   // по умолчанию: 0 и 1 служебные
        this._controlBusCount = 2; // по умолчанию: 0 и 1 служебные
        
        // Активные кабели (для отслеживания)
        this._activeCables = [];

        this._converterBuses = {};   // key: `${cableId}_${inputId}` -> { type, sourceBus, bus }
        
        // маппинг кабель -> номер шины
        this._cableBusMap = {};      // cableId -> busNumber
        this._audioBusCounter = 2;   // следующий свободный номер для audio
        this._controlBusCounter = 2; // следующий свободный номер для control
        this._availableAudioBuses = [];   // освободившиеся audio номера
        this._availableControlBuses = []; // освободившиеся control номера
        // Шаблон Csound (будет обновляться динамически)      
        for (const udo of BASE_UDOS) this.includes.add(udo); 
        // ⭐ Scope tables
        this._scopeTables = new Map();      // cableId -> { tableNum, bus, isAudio }
        this._scopeTableCounter = 9000;

        // ⭐ UDO text cache (invalidation via invalidateUdoCache())
        this._udoTextCache = new Map();     // udoPath -> text | null

        // ⭐ Diagnostic counters (reset per generateOrc)
        this._fetchStats = { count: 0, ms: 0, byPath: {} };
        }
    /**
     * Загрузить UDO по пути, как он хранится в this.includes.
     *  - "user/MultiOsc.txt"     → moduleStore (localStorage / Tauri fs)
     *  - "9.txt", "led_rms.txt"  → fetch из public/csound/modules/
     *
     * Возвращает строку UDO или null.
     */
    /**
     * Load a UDO by its stored path.
     * Caches text in-memory; use invalidateUdoCache() on hot-reload.
     *  - "library/<lib>/<Name>.txt"  → libraryStore.loadUdo()
     *  - "led_rms.txt", "mVU_rms.txt" → fetch('/csound/modules/...')
     */
    async _loadUdoByPath(udoPath) {
        if (!udoPath) return null;

        if (this._udoTextCache.has(udoPath)) {
            return this._udoTextCache.get(udoPath);
        }

        const t0 = performance.now();
        let text = null;
        try {
            text = await this._loadUdoByPathUncached(udoPath);
        } finally {
            const dt = performance.now() - t0;
            this._fetchStats.count++;
            this._fetchStats.ms += dt;
            this._fetchStats.byPath[udoPath] = (this._fetchStats.byPath[udoPath] || 0) + dt;
        }

        this._udoTextCache.set(udoPath, text);
        return text;
    }

    async _loadUdoByPathUncached(udoPath) {
        // 1. Library module: "library/<lib>/<Name>.txt"
        const mLib = udoPath.match(/^library\/([^/]+)\/(.+)\.txt$/);
        if (mLib) {
            const [, lib, name] = mLib;
            try {
                const text = await libraryStore.loadUdo(lib, name);
                if (!text) {
                    console.warn(`⚠️ Library UDO not found: ${lib}/${name}`);
                }
                return text;
            } catch (e) {
                console.warn(`⚠️ Failed to load library UDO: ${lib}/${name}`, e);
                return null;
            }
        }

        // 2. Built-in UDO from public/csound/modules/
        try {
            const response = await fetch(`/csound/modules/${udoPath}`);
            if (!response.ok) return null;

            const text = await response.text();

            if (/<!DOCTYPE|<html[\s>]/i.test(text.slice(0, 200))) {
                console.warn(`⚠️ Got HTML instead of UDO for ${udoPath} — file missing`);
                return null;
            }

            return text;
        } catch (e) {
            console.warn(`⚠️ Failed to load UDO: ${udoPath}`, e);
            return null;
        }
    }

    /**
     * Invalidate cached UDO text and parsed variants.
     * @param {RegExp} [pattern] — only paths matching pattern; omit to clear all
     */
    invalidateUdoCache(pattern) {
        if (!pattern) {
            this._udoTextCache.clear();
            this._variantsCache = {};
            return;
        }
        for (const k of [...this._udoTextCache.keys()]) {
            if (pattern.test(k)) this._udoTextCache.delete(k);
        }
        if (this._variantsCache) {
            for (const k of Object.keys(this._variantsCache)) {
                if (pattern.test(k)) delete this._variantsCache[k];
            }
        }
    }
    async loadUdoContent(pathOrTypeId) {
        let path = String(pathOrTypeId);
        if (!path.endsWith('.txt')) path += '.txt';
        return this._loadUdoByPath(path);
    }

    async loadAllUdoContents() {
        return this._loadOrderedUdos();
    }

    // Shared UDO dependencies precede their callers and are emitted once.
    async _loadOrderedUdos() {
        const contents = [], visited = new Set(), visiting = new Set();
        const visit = async (path, required = false) => {
            if (visited.has(path)) return;
            if (visiting.has(path)) throw new Error(`Circular UDO dependency: ${path}`);
            visiting.add(path);
            const content = await this._loadUdoByPath(path);
            if (!content) throw new Error(`UDO ${required ? 'dependency ' : ''}not available: ${path}`);
            for (const match of content.matchAll(/^;\s*@\s*requires\s+([A-Za-z0-9_-]+\.txt)\s*$/gm)) {
                await visit(match[1], true);
            }
            visiting.delete(path);
            visited.add(path);
            contents.push(content);
        };
        for (const path of [...this.includes].sort()) await visit(path);
        return contents;
    }

    async generateOrc() {
        await this._loadVariantsForModules(); 
        this._prepareVariants();  
        this._prepareConverters();
        // ⭐ Scope code
        const scopeCode = this._generateScopeCode();
        // ⭐ 0. Собираем mapping ftgen (перед остальным)
        const mappingFtgens = await this._collectMappingFtgens();
        
        this._fetchStats = { count: 0, ms: 0, byPath: {} };

        const udoContents = await this._loadOrderedUdos();
        const sampleTables = udoContents.some(text => /opcode\s+GrainSample\s*,/.test(text))
            ? this.system.csoundEngine.grainSamples.orchestra() : '';

        const udoString = udoContents.join('\n\n');

        const fs = this._fetchStats;
        console.log('[generateOrc] fetchStats:', {
            count: fs.count,
            totalMs: Math.round(fs.ms),
            slowest: Object.entries(fs.byPath)
                .sort((a, b) => b[1] - a[1])
                .slice(0, 5)
                .map(([p, ms]) => `${p} — ${Math.round(ms)}ms`),
        });
        
        // ⭐ 2. Собираем модули из патча (voice и fx)
        const voiceModules = Array.from(this.modules.values())
            .filter(m => m.layer === 'voice')
            .map(m => this.formatModuleLine(m))
            .join('\n');
        
        const fxModules = Array.from(this.modules.values())
            .filter(m => m.layer === 'fx')
            .map(m => this.formatModuleLine(m))
            .join('\n');
        
        // ⭐ 3. Zakinit
        const zakinitString = this.getZakInitString();
        

        // ⭐ 4. ПОЛЬЗОВАТЕЛЬСКИЕ МОДУЛИ
        // Управляются через this.includes (user/*.txt), а не через this.userModules.
        // this.userModules остаётся как реестр метаданных, но НЕ вставляется в ORC.
        const userModulesCode = '';
        
        // ⭐ 5. Формируем полный ORC
        return `
    sr = 48000
    ksmps = 4
    nchnls = 2
    0dbfs = 1.0

    gkBPM init 120
    gkMVOL init 1
    gaFX1 init 0
    gaFX2 init 0
    gaFX3 init 0
    gaFX4 init 0

    opcode K2Y, k, k
        kin xin
        kout = (kin > 0 ? 1 : 0)
        xout kout
    endop

    opcode A2O, a, a
        ; setksmps 1  ; ⭐ закомментировано для стабильности
        ain xin
        kin = k(ain)
        kout = (kin > 0 ? 1 : 0)
        xout a(kout)
    endop

    ; -------- converters (strict inputs) --------
    opcode K2A, 0, kk
        kzkIn, kzaOut xin
        kIn zkr kzkIn
        zaw a(kIn), kzaOut
    endop

    opcode A2K, 0, kk
        kzaIn, kzkOut xin
        aIn zar kzaIn
        zkw k(aIn), kzkOut
    endop

    gkNote init 64
    gkGate init 0
    ${zakinitString}
    massign 1,0
    massign 2,0
    massign 3,0
    massign 4,0

    giSin ftgen 1, 0, 16384, 10, 1
    giCos ftgen 11, 0, 16384, 11, 1, 1
    giTri ftgen 2, 0, 16384, 7, 0, 4096, 1, 8192, -1, 4096, 0
    giTriF ftgen 24, 0, 16384, 7, -1, 8192, 1, 8192, -1
    giSaw ftgen 3, 0, 16384, 7, 1, 16384, -1
    giSqr50 ftgen 4, 0, 16384, 7, 1, 8192, 1, 0, -1, 8192, -1
    giSqr25 ftgen 5, 0, 16384, 7, 1, 4096, 1, 0, -0.25, 12288, -0.25
    giSqr10 ftgen 6, 0, 16384, 7, 1, 1024, 1, 0, -0.0625, 15360, -0.0625
    giSq400 ftgen 21, 0, 16384, 7,1,41,1,0,0,16343,0
    giSq96 ftgen 22, 0, 16384, 7,1,1366,1,0,0,15018,0
    giSq16 ftgen 23, 0, 16384, 7,1,910,1,0,0,15474,0
    ;---------------------------------
    ; MAPPING TABLES (auto from value_maps.json)
    ${mappingFtgens}
    ;---------------------------------
    ; SCOPE TABLES (oscilloscope ring buffers)
    ${scopeCode.ftgens}
    ;---------------------------------
    ; UDO section (inlined from /csound/modules/*.txt)
    ${sampleTables}
    ${udoString}

    ;---------------------------------
    ; VOICE AREA
    instr 1
    ${voiceModules || '; no voice modules'}
    ${scopeCode.voiceTables}
    endin

    ;---------------------------------
    ; FX AREA
    instr 2
    ${fxModules || '; no fx modules'}
    ${scopeCode.fxTables}
    endin

    ;---------------------------------
    ; GLOBAL MIDI
    gkstat init 0
    gkchan init 0
    gkdata1 init 0
    gkdata2 init 0
    instr 3
      gkstat, gkchan, gkdata1, gkdata2 midiin
      if gkstat != 144 goto Next
        gkGate = 1
        gkNote = gkdata1
    Next:
      if gkstat!=128 goto Over
        gkGate = 0
    Over:
      if (gkdata1 != 0) && (gkdata2 == 0) then
            gkGate = 0
      endif 
    ;printk2 gkGate
    endin

    ;---------------------------------
    ; FOR OFFLINE RENDERING 
    instr 4
      xtratim 0.1
      gkGate linsegr 1, p3, 1, 0, 0
      gkNote = p4
    endin
    ;=================================
    instr 5
        kBPM chnget "bpm"
        kBPM limit kBPM, 1, 300
        gkBPM = kBPM
        kMasterVol chnget "mvol"
        kMasterVol portk kMasterVol, 0.1
        gkMVOL = kMasterVol         
    endin
    `;
    }

    generateSco() {
        // Пока пусто — ноты будут добавляться через inputMessage
        // Но для инициализации можно оставить пустым или с тестовой нотой
        return `
    i1 0 [60*60*24*7]
    i2 0 [60*60*24*7]
    i3 0 [60*60*24*7]
    ; use i4 to emulate MIDI commands if needed
    ;i4 0 1 64
    i5 0 [60*60*24*7]
    `;
    }


    /**
     * Извлечь имена mapping-таблиц из DSP-кода модуля.
     * Ищем строки вида:
     *   ;@ map FLTphs LFOlow
     */
    _extractMappingTablesFromUdo(udoText) {
        const names = [];
        if (!udoText) return names;
        
        // Ищем все вхождения ;@ map
        const regex = /^;\s*@\s*map\s+(.+)$/gm;
        let match;
        while ((match = regex.exec(udoText)) !== null) {
            const parts = match[1].trim().split(/\s+/);
            parts.forEach(p => {
                if (p) names.push(p);
            });
        }
        return names;
    }


    async _collectMappingFtgens() {
        const usedNames = new Set();
        
        // 1. Для каждого модуля в патче — читаем его UDO-файл
        for (const moduleData of this.modules.values()) {
            const udoPath = moduleData.udoPath;
            if (!udoPath) continue;

            try {
                const udoText = await this._loadUdoByPath(udoPath);
                if (!udoText) continue;

                const names = this._extractMappingTablesFromUdo(udoText);
                names.forEach(n => usedNames.add(n));
            } catch (e) {
                console.warn(`⚠️ Could not read UDO ${udoPath}:`, e);
            }
        }
        
        console.log('🔍 usedNames from UDO files:', [...usedNames]);
        
        if (usedNames.size === 0) {
            return '; no mapping tables in use';
        }
        
        // 2. Достаём сами таблицы
        const mappingTables = this.system?.mappingTables;
        if (!mappingTables || mappingTables.getCount() === 0) {
            console.warn('⚠️ MappingTables not loaded');
            return '; mapping tables not loaded';
        }
        
        // 3. Генерируем ftgen
        const lines = [];
        let tableNumber = 1000;
        const sortedNames = [...usedNames].sort();
        
        for (const name of sortedNames) {
            const values = mappingTables.get(name);
            if (!values || !Array.isArray(values) || values.length === 0) {
                console.warn(`⚠️ Mapping table "${name}" empty or missing`);
                continue;
            }
            
            const valuesStr = values.join(', ');
            lines.push(`gi${name} ftgen ${tableNumber}, 0, ${values.length}, -2, ${valuesStr}`);
            console.log(`📊 ftgen ${tableNumber} ← "${name}" (${values.length} values)`);
            tableNumber++;
        }
        
        return lines.length > 0 ? lines.join('\n') : '; no mapping tables generated';
    }


    // ============================================
    // SCOPE (осциллограф)
    // ============================================

    addScopeTable(cable) {
        if (!cable) return null;
        if (this._scopeTables.has(cable.id)) {
            return this._scopeTables.get(cable.id).tableNum;
        }

        const bus = this._cableBusMap[cable.id];
        if (bus === undefined) {
            console.warn(`[CsoundGenerator] addScopeTable: cable ${cable.id} has no bus`);
            return null;
        }

        const isAudio = this._getCableType(cable) === 'audio';
        const tableNum = this._scopeTableCounter++;

        this._scopeTables.set(cable.id, { tableNum, bus, isAudio });
        console.log(`[CsoundGenerator] 📊 Scope table ${tableNum} ← cable ${cable.id.substr(0,8)} (bus ${bus}, ${isAudio ? 'audio' : 'control'})`);
        return tableNum;
    }

    removeScopeTable(cableId) {
        if (this._scopeTables.delete(cableId)) {
            console.log(`[CsoundGenerator] 📊 Removed scope table for cable ${cableId.substr(0,8)}`);
        }
    }

    getScopeTableNum(cableId) {
        return this._scopeTables.get(cableId)?.tableNum ?? null;
    }

    _generateScopeCode() {
        if (this._scopeTables.size === 0) {
            return { ftgens: '; no scope tables', voiceTables: '', fxTables: '' };
        }

        const ftgenLines = [];
        const voiceLines = [];
        const fxLines = [];

        for (const [cableId, info] of this._scopeTables) {
            ftgenLines.push(`giScope_${info.tableNum} ftgen ${info.tableNum}, 0, 4096, 2, 0`);

            const cable = this._activeCables.find(c => c.id === cableId);
            const layer = cable?.fromJack?.parentModule?.layer || 'voice';

            const lines = [];

            // k-rate phasor: за 4096 k-блоков проходит 0..1
            // krate = sr/ksmps, поэтому частота = (sr/ksmps) / 4096
            lines.push(`aScopeIdx_${info.tableNum} phasor (sr / ksmps) / 4096`);

            if (info.isAudio) {
                lines.push(`aScopeSig_${info.tableNum} zar ${info.bus}`);
                lines.push(`tablew aScopeSig_${info.tableNum}, aScopeIdx_${info.tableNum}, ${info.tableNum}, 1`);
            } else {
                lines.push(`kScopeSig_${info.tableNum} zkr ${info.bus}`);
                lines.push(`tablew kScopeSig_${info.tableNum}, k(aScopeIdx_${info.tableNum}), ${info.tableNum}, 1`);
            }

            if (layer === 'fx') fxLines.push(...lines);
            else voiceLines.push(...lines);
        }

        return {
            ftgens: ftgenLines.join('\n'),
            voiceTables: voiceLines.length ? voiceLines.join('\n') : '; no voice scope tables',
            fxTables: fxLines.length ? fxLines.join('\n') : '; no fx scope tables',
        };
    }


    /**
     * Добавить кабель
     */
    addCable(cable) {
        this._activeCables.push(cable);
        // ⭐ Назначаем номер шины
        this._assignBusNumberToCable(cable);
        this._updateZakInit();
        this.log(`🔌 Added cable, zakinit updated`);
    }

    _prepareConverters() {
        this._converterBuses = {};
        
        // Защита: счётчики не должны отставать от count
        this._audioBusCounter = Math.max(this._audioBusCounter, this._audioBusCount);
        this._controlBusCounter = Math.max(this._controlBusCounter, this._controlBusCount);
        
        let found = 0;
        
        for (const moduleData of this.modules.values()) {
            const panel = this.getPanelById(moduleData.instanceId);
            if (!panel) continue;
            
            const moduleDef = this.system?.moduleFactory?.moduleRegistry?.[moduleData.typeId];
            if (!moduleDef) continue;
            
            const inputIds = moduleDef.inputs || [];
            
            for (const inputId of inputIds) {
                const cable = this._findCableForPort(moduleData.instanceId, inputId, 'input');
                if (!cable) continue;
                
                // ⭐ Csound-rate источника (logic/logicAudio схлопываются в control/audio)
                const sourceRate = this._getCableType(cable);   // 'audio' | 'control'
                
                const inputComp = panel.components.find(
                    c => String(c.id) === String(inputId)
                );
                // ⭐ Csound-rate приёмника
                const inputRate = (inputComp?.type === 'audio' || inputComp?.type === 'logicAudio')
                                  ? 'audio'
                                  : 'control';
                
                // ⭐ Если rate совпадает — конвертер не нужен
                // (logic ↔ logicAudio, control ↔ logic, audio ↔ logicAudio)
                if (sourceRate === inputRate) continue;
                
                let convType;
                if (sourceRate === 'control' && inputRate === 'audio') {
                    convType = 'K2A';
                } else if (sourceRate === 'audio' && inputRate === 'control') {
                    convType = 'A2K';
                } else {
                    console.warn(`[CsoundGenerator] Unsupported conversion: ${sourceRate} → ${inputRate}`);
                    continue;
                }
                
                const sourceBus = this._cableBusMap[cable.id];
                if (sourceBus === undefined) {
                    console.warn(`[CsoundGenerator] Cable ${cable.id.substr(0, 8)} has no bus`);
                    continue;
                }
                
                let newBus;
                if (inputRate === 'audio') {
                    newBus = this._audioBusCounter++;
                    this._audioBusCount = this._audioBusCounter;
                } else {
                    newBus = this._controlBusCounter++;
                    this._controlBusCount = this._controlBusCounter;
                }
                
                const key = `${cable.id}_${inputId}`;
                this._converterBuses[key] = {
                    type: convType,
                    sourceBus,
                    bus: newBus,
                };
                
                found++;
                console.log(`[CsoundGenerator] Converter: ${convType} (src: ${sourceRate}-bus ${sourceBus} → dst: ${inputRate}-bus ${newBus}) (module ${moduleData.instanceName}/${inputId})`);
            }
        }
        
        console.log(`[CsoundGenerator] _prepareConverters: found ${found} converter(s)`);
    }
    
    /**
     * Назначить номер шины кабелю
     */
    _assignBusNumberToCable(cable) {
        if (this._cableBusMap[cable.id] !== undefined) {
            return;
        }
        
        // Проверяем, есть ли уже кабель с таким же выходом
        const outputJack = cable.fromJack;
        if (outputJack) {
            const existingCable = this._activeCables.find(c => 
                c.fromJack === outputJack && 
                c.id !== cable.id &&
                this._cableBusMap[c.id] !== undefined
            );
            if (existingCable) {
                const busNumber = this._cableBusMap[existingCable.id];
                this._cableBusMap[cable.id] = busNumber;
                this.log(`🔢 Cable ${cable.id.substr(0, 8)} → bus ${busNumber} (shared from same output)`);
                return;
            }
        }
        
        const cableType = this._getCableType(cable);
        let busNumber;
        
        if (cableType === 'audio') {
            // ⭐ Сначала проверяем освободившиеся номера
            if (this._availableAudioBuses.length > 0) {
                this._availableAudioBuses.sort((a, b) => a - b);
                busNumber = this._availableAudioBuses.shift();
            } else {
                busNumber = this._audioBusCounter++;
            }
        } else {
            if (this._availableControlBuses.length > 0) {
                this._availableControlBuses.sort((a, b) => a - b);
                busNumber = this._availableControlBuses.shift();
            } else {
                busNumber = this._controlBusCounter++;
            }
        }
        
        this._cableBusMap[cable.id] = busNumber;
        this.log(`🔢 Cable ${cable.id.substr(0, 8)} → bus ${busNumber} (${cableType})`);
    }


    getBusNumberForCable(cable) {
        return this._cableBusMap[cable.id];
    }
    
    removeCable(cable) {
        const index = this._activeCables.indexOf(cable);
        if (index > -1) {
            this._activeCables.splice(index, 1);
            
            // ⭐ Освобождаем номер шины для переиспользования
            if (this._cableBusMap[cable.id] !== undefined) {
                const busNumber = this._cableBusMap[cable.id];
                const cableType = this._getCableType(cable);
                
                // Проверяем, не использует ли этот номер другой кабель (от того же выхода)
                const isShared = this._activeCables.some(c => 
                    c.id !== cable.id && 
                    this._cableBusMap[c.id] === busNumber
                );
                
                if (!isShared) {
                    // Номер больше не используется → добавляем в доступные
                    if (cableType === 'audio') {
                        this._availableAudioBuses.push(busNumber);
                    } else {
                        this._availableControlBuses.push(busNumber);
                    }
                    this.log(`🔢 Bus ${busNumber} freed (${cableType})`);
                }
                
                delete this._cableBusMap[cable.id];
                // ⭐ Убираем scope-таблицу этого кабеля
                this.removeScopeTable(cable.id);
            }
            
            this._updateZakInit();
            this.log(`🔌 Removed cable, zakinit updated`);
        }
    }
    
    /**
     * Очистить все кабели
     */
    clearCables() {
        this._activeCables = [];
        this._cableBusMap = {};
        this._audioBusCounter = 2;
        this._controlBusCounter = 2;
        this._updateZakInit();
        this.log(`🔌 All cables cleared, zakinit reset`);
    }
    
    /**
     * Обновить zakinit на основе кабелей
     */
    _updateZakInit() {
        let audioCount = 0;
        let controlCount = 0;
        
        for (const cable of this._activeCables) {
            const cableType = this._getCableType(cable);
            if (cableType === 'audio') {
                audioCount++;
            } else if (cableType === 'control') {
                controlCount++;
            }
        }
        
        this._audioBusCount = 2 + audioCount;
        this._controlBusCount = 2 + controlCount;
        
        //console.log(`🎛️ zakinit: audio=${this._audioBusCount} (2 + ${audioCount}), control=${this._controlBusCount} (2 + ${controlCount})`);
    }
    
    _getCableType(cable) {
        // ⭐ 1. ПРИОРИТЕТ: тип источника с учётом варианта
        const sourceType = this._resolveSourceType(cable);
        if (sourceType === 'audio' || sourceType === 'logicAudio') return 'audio';
        if (sourceType === 'control' || sourceType === 'logic') return 'control';
        
        // ⭐ 2. Fallback: тип приёмника
        const destType = cable.toJack?.type;
        if (destType === 'audio' || destType === 'logicAudio') return 'audio';
        if (destType === 'control' || destType === 'logic') return 'control';
        
        // ⭐ 3. Совсем fallback: по цвету (старое поведение)
        const color = cable.getDisplayColor ? cable.getDisplayColor() : cable.color;
        const audioColors = ['#ef4444', '#ff0000', '#ff4444', '#ff6b6b', '#ff8800', '#ffa500', '#ff8c00', '#f97316'];
        const controlColors = ['#3b82f6', '#0000ff', '#4488ff', '#fde047', '#ffff00', '#ffd93d', '#ffdd57'];
        
        if (!color) return 'audio';
        const colorLower = color.toLowerCase();
        for (const c of audioColors) if (colorLower === c.toLowerCase()) return 'audio';
        for (const c of controlColors) if (colorLower === c.toLowerCase()) return 'control';
        
        return 'audio';
    }
    
    /**
     * Получить строку zakinit
     */
    getZakInitString() {
        return `zakinit ${this._audioBusCount}, ${this._controlBusCount}`;
    }


    /**
     * Для каждого модуля в патче — читает его UDO, парсит variants,
     * сохраняет в moduleDef (moduleFactory.moduleRegistry[typeId]).
     * Кэширует по udoPath.
     */
    async _loadVariantsForModules() {
        if (!this._variantsCache) this._variantsCache = {};
        
        for (const moduleData of this.modules.values()) {
            const { typeId, udoPath } = moduleData;
            if (!udoPath || !typeId) continue;
            
            // Кэш — не перечитываем один и тот же файл
            let variants = this._variantsCache[udoPath];
            if (variants === undefined) {
                try {
                    const udoText = await this._loadUdoByPath(udoPath);
                    if (!udoText) {
                        this._variantsCache[udoPath] = null;
                        continue;
                    }
                    variants = this._parseVariants(udoText);
                    this._variantsCache[udoPath] = variants;
                } catch (e) {
                    console.warn(`[CsoundGenerator] variants load failed: ${udoPath}`, e);
                    this._variantsCache[udoPath] = null;
                    continue;
                }
            }
            
            // Сохраняем в moduleDef
            const moduleDef = this.system?.moduleFactory?.moduleRegistry?.[typeId];
            if (moduleDef && variants) {
                moduleDef.variants = variants.variants;
                moduleDef.defaultSuffix = variants.defaultSuffix;
                moduleDef.strict = variants.strict;
            }
        }
    }


    _prepareVariants() {
        // 1. Сброс — все модули в дефолт
        for (const moduleData of this.modules.values()) {
            const moduleDef = this.system?.moduleFactory?.moduleRegistry?.[moduleData.typeId];
            if (!moduleDef?.variants || moduleDef.variants.length < 2) {
                moduleData._activeVariant = null;
                continue;
            }
            moduleData._activeVariant = moduleDef.defaultSuffix || 'k';
        }
        
        // 2. Итерация до стабилизации
        const MAX_ITER = 20;
        let iter = 0;
        let changed = true;
        
        while (changed && iter < MAX_ITER) {
            changed = false;
            iter++;
            
            for (const moduleData of this.modules.values()) {
                const moduleDef = this.system?.moduleFactory?.moduleRegistry?.[moduleData.typeId];
                if (!moduleDef?.variants || moduleDef.variants.length < 2) continue;
                
                const inputIds = moduleDef.inputs || [];
                const strict = moduleDef.strict || [];
                const defaultSuffix = moduleDef.defaultSuffix || 'k';
                
                // Ищем audio-кабель на триггерном входе
                let forceAudio = false;
                
                for (let i = 0; i < inputIds.length; i++) {
                    if (strict[i] === 1) continue;
                    
                    const inputId = inputIds[i];
                    const cable = this._findCableForPort(moduleData.instanceId, inputId, 'input');
                    if (!cable) continue;
                    
                    // ⭐ Тип источника с учётом активного варианта модуля-источника
                    const sourceType = this._resolveSourceType(cable);
                    
                    if (sourceType === 'audio') {
                        forceAudio = true;
                        break;
                    }
                }
                
                // Желаемый режим
                let desiredSuffix = defaultSuffix;
                if (forceAudio) {
                    const targetVariant = moduleDef.variants.find(v => v.suffix === 'a');
                    if (targetVariant) desiredSuffix = 'a';
                }
                
                // Если изменилось — фиксируем
                if (moduleData._activeVariant !== desiredSuffix) {
                    moduleData._activeVariant = desiredSuffix;
                    changed = true;
                }
            }
        }
        
        if (iter > 1) {
            console.log(`[CsoundGenerator] _prepareVariants: стабилизировано за ${iter} итераций`);
        }
        
        // Лог переключённых
        let switched = 0;
        for (const moduleData of this.modules.values()) {
            const moduleDef = this.system?.moduleFactory?.moduleRegistry?.[moduleData.typeId];
            if (!moduleDef?.variants || moduleDef.variants.length < 2) continue;
            const def = moduleDef.defaultSuffix || 'k';
            if (moduleData._activeVariant && moduleData._activeVariant !== def) {
                switched++;
            }
        }
        if (switched > 0) {
            console.log(`[CsoundGenerator] _prepareVariants: ${switched} module(s) switched from default`);
        }
    }

    _resolveSourceType(cable) {
        const fromJack = cable.fromJack;
        if (!fromJack) return 'audio';

        const t = fromJack.type || 'audio';

        // logic-семейство — как есть
        if (t === 'logic' || t === 'logicAudio') return t;

        // ⭐ Если джек источника уже 'audio' — доверяем цвету, не перепроверяем вариант.
        //    Иначе audio-выход источника с default 'k' читается как 'control',
        //    и получатель не переключается на 'a' (замкнутый круг при порядке Map).
        if (t === 'audio') return 'audio';

        // t === 'control' — проверяем, не audio ли источник по варианту
        const sourcePanel = fromJack.parentModule;
        if (!sourcePanel) return 'control';

        const sourceModuleData = [...this.modules.values()]
            .find(m => m.instanceId === sourcePanel.jsonId);

        if (sourceModuleData) {
            const sourceDef = this.system?.moduleFactory?.moduleRegistry?.[sourceModuleData.typeId];
            if (sourceDef?.variants && sourceDef.variants.length > 1) {
                const active = sourceModuleData._activeVariant || sourceDef.defaultSuffix || 'k';
                return active === 'a' ? 'audio' : 'control';
            }
        }

        return 'control';
    }


/**
 * Найти кабель, подключенный к порту (входу)
 */
    _findCableForPort(moduleId, componentId, direction) {
        const targetId = parseInt(componentId);
        
        for (const cable of this._activeCables) {
            const jack = direction === 'input' ? cable.toJack : cable.fromJack;
            if (!jack) continue;
            
            let parentId = jack.parentModule?.jsonId || jack.parentModule?.moduleId;
            if (!parentId && jack.module) {
                parentId = jack.module.jsonId || jack.module.moduleId;
            }
            if (!parentId && jack.parent) {
                parentId = jack.parent.jsonId || jack.parent.moduleId;
            }
            
            if (parentId !== moduleId) continue;
            
            // ⭐ Сравниваем по ID компонента
            if (parseInt(jack.id) === targetId) {
                return cable;
            }
        }
        return null;
    }


    addModule(moduleData) {
        //console.log('🎯 addModule called with:', moduleData);
        
        const { 
            typeId,           // ключ в moduleRegistry (уже не numericTypeId)
            instanceId,       
            instanceName,     
            layer,            
            parameters = [],  
            mode = [],        
            defaultParams = [],
            defaultMode = [], 
            inlets = 1,       
            outlets = 1,   
            isUser = false  
        } = moduleData;

        // ⭐ Библиотека модуля — из definition (проставляется ModuleFactory.loadModule).
        //    Fallback 'user' для старых регистраций (preloadStatuses в DEV и т.п.)
        const moduleDef = this.system?.moduleFactory?.moduleRegistry?.[typeId];
        const lib = moduleDef?.library || (isUser ? 'user' : 'user');

        // ⭐ UDO-путь: "library/<lib>/<Name>.txt"
        const filename = `library/${lib}/${typeId}.txt`;        

        if (!this.includes.has(filename)) {
            this.includes.add(filename);
        }
        // Сохраняем модуль с правильным typeId
        const moduleKey = `${instanceName}_${instanceId}`;
        this.modules.set(moduleKey, {
            typeId,
            instanceId,
            instanceName,
            layer,
            parameters,
            mode,
            defaultParams,
            defaultMode,
            inlets,
            outlets,
            isUser,
            udoPath: filename,
        });
    }
    
    removeModule(instanceId, instanceName, typeId, layer) {
        const moduleKey = `${instanceName}_${instanceId}`;
        
        if (!this.modules.has(moduleKey)) {
            this.log(`⚠️ Module not found: ${moduleKey}`, 'dim');
            return false;
        }
        
        // ⭐ Получаем udoPath ДО удаления
        const removedModule = this.modules.get(moduleKey);
        const udoPath = removedModule?.udoPath;
        
        this.modules.delete(moduleKey);
        this.log(`🗑️ Removed module: ${moduleKey}`);
        
        // ⭐ Проверяем, используется ли ещё этот UDO
        const pathStillUsed = Array.from(this.modules.values())
            .some(m => m.udoPath === udoPath);
        
        if (!pathStillUsed && udoPath) {
            this.includes.delete(udoPath);
            this.log(`📄 Removed include: ${udoPath}`);
        }
        
        return true;
    }
    
/**
 * Сгенерировать полный CSD (для экспорта в файл) - НОВАЯ ВЕРСИЯ
 */
    async generateFullCsd() {
        const orc = await this.generateOrc();
        return `<CsoundSynthesizer>
    <CsOptions>
    -odac -d -m16
    </CsOptions>
    <CsInstruments>
    ${orc}
    </CsInstruments>
    <CsScore>
    i1 0 [60*60*24*7]
    i2 0 [60*60*24*7]
    i3 0 [60*60*24*7]
    i5 0 [60*60*24*7]
    </CsScore>
    </CsoundSynthesizer>`;
    }
    
    formatModuleLine(module) {
        const {
            instanceName,
            instanceId,
            parameters = [],
            mode = [],
            defaultParams = [],
            defaultMode = [],
            inlets,
            outlets,
            typeId,
            numericTypeId
        } = module;

        const panel = this.getPanelById(instanceId);
        const moduleDef = this.system?.moduleFactory?.moduleRegistry?.[typeId];

        // ⭐ Имя модуля (opcode)
        let moduleName = typeId;
        if (moduleDef && moduleDef.type) {
            moduleName = moduleDef.type;
        }

        // ⭐ Суффикс добавляем при наличии defaultSuffix, даже если варианта одна:
        //    opcode в UDO может называться <type>_<suffix> (например TestOsc_k).
        if (moduleDef?.variants?.length > 0 && moduleDef.defaultSuffix) {
            const suffix = module._activeVariant || moduleDef.defaultSuffix;
            moduleName = `${moduleDef.type}_${suffix}`;
        }

        const inputIds = moduleDef?.inputs || [];
        const outputIds = moduleDef?.outputs || [];

        // ⭐ 1. inletBuses (как раньше) — шины, которые читает opcode модуля
        const inletBuses = inputIds.map(id => {
            const cable = this._findCableForPort(instanceId, id, 'input');
            if (!cable) return 1; // fallback: служебная шина (как было)

            const sourceBus = this._cableBusMap[cable.id];
            if (sourceBus === undefined) return 1;

            const convKey = `${cable.id}_${id}`;
            const conv = this._converterBuses[convKey];
            if (conv) return conv.bus;

            return sourceBus;
        });

        // ⭐ 2. outletBuses (как раньше, но с tap-шинами для индикаторов на Output)
        //    Сначала собираем tap-потребности, потом досоздаём шины.
        const outletBuses = outputIds.map(id => {
            const cables = this._findCablesForOutput(instanceId, id);
            if (cables.length > 0) {
                const busNumber = this._cableBusMap[cables[0].id];
                if (busNumber !== undefined) return busNumber;
            }
            return 0;
        });

        // ⭐ 3. Индикаторы: LED и MiniVU
        const leds = (panel?.components || []).filter(c => c.constructor.name === 'LED');
        const mvus = (panel?.components || []).filter(c => c.constructor.name === 'MiniVU');

        // Карта tap-точек: ключ = `${dir}:${componentId}` → { bus, type, a2kBus }
        // dir = 'output' | 'input'
        const taps = new Map();

        // 3a. Обрабатываем Output-индикаторы: гарантируем tap-шину
        const handleOutputTap = (srcComp, srcIndex) => {
            const key = `output:${srcComp.id}`;
            if (taps.has(key)) return taps.get(key);

            const outType = this._normalizeJackType(srcComp);
            let bus = outletBuses[srcIndex];

            if (!bus || bus === 0) {
                // Нет кабеля — выделяем tap-шину того же типа, что Output
                const busType = (outType === 'audio') ? 'audio' : 'control';
                bus = this._allocateBus(busType);
                outletBuses[srcIndex] = bus; // opcode теперь пишет в неё
            }

            const tap = { bus, type: outType, a2kBus: null };
            taps.set(key, tap);
            return tap;
        };

        // 3b. Обрабатываем Input-индикаторы: берём inletBuses[srcIndex]
        //     Если кабеля нет (inletBuses = 1) — индикатор не генерируем.
        const handleInputTap = (srcComp, srcIndex) => {
            const key = `input:${srcComp.id}`;
            if (taps.has(key)) return taps.get(key);

            // Проверяем, есть ли реальный кабель на этот вход
            const cable = this._findCableForPort(instanceId, srcComp.id, 'input');
            if (!cable) return null; // нет кабеля — индикатор пропускаем

            const bus = inletBuses[srcIndex];
            if (!bus || bus === 1) return null; // fallback-шина — пропускаем

            const inType = this._normalizeJackType(srcComp);
            const tap = { bus, type: inType, a2kBus: null };
            taps.set(key, tap);
            return tap;
        };

        // 3c. Регистрируем все tap-точки, на которые ссылаются индикаторы
        for (const ind of [...leds, ...mvus]) {
            const src = this._resolveIndicatorSource(panel, ind, inputIds, outputIds);
            if (!src) continue;
            if (src.dir === 'output') handleOutputTap(src.comp, src.index);
            else handleInputTap(src.comp, src.index);
        }

        // 3d. Для LED на audio-tap выделяем A2K (один раз на точку)
        for (const ind of leds) {
            const src = this._resolveIndicatorSource(panel, ind, inputIds, outputIds);
            if (!src) continue;
            const key = `${src.dir}:${src.comp.id}`;
            const tap = taps.get(key);
            if (!tap) continue;
            if (tap.type === 'audio' && tap.a2kBus === null) {
                tap.a2kBus = this._allocateBus('control');
            }
            // control/logic → LED читает tap.bus напрямую
        }

        // ⭐ 4. chnget для параметров
        const hasParamsField = Array.isArray(moduleDef?.params);
        const paramIds = hasParamsField ? moduleDef.params : [];

        const chngetLines = [];
        const paramArgs = [];   // ⭐ объявлены ОДИН РАЗ до всех ветвей

        if (paramIds.length > 0) {
            // chnget-путь: новые модули с параметрами
            paramIds.forEach(compId => {
                const comp = panel?.components.find(
                    c => String(c.id) === String(compId)
                );
                if (!comp) {
                    console.warn(`  ⚠️ Param id=${compId} not found in panel`);
                    paramArgs.push('0');
                    return;
                }
                const channelName = `module_${instanceName}_${instanceId}_${compId}`;
                const varName = `k_${instanceName}_${instanceId}_${compId}`;
                chngetLines.push(`${varName} chnget "${channelName}"`);
                paramArgs.push(varName);
            });
        } else if (hasParamsField) {
            // ⭐ params: [] — явно нет параметров. НЕ fallback.
            // paramArgs остаётся [] — в вызов уйдут только inlets + outlets.
        } else {
            // legacy: у модуля нет поля params вообще
            const paramsToUse = parameters.length > 0 ? parameters : defaultParams;
            paramsToUse.forEach(p => paramArgs.push(String(p)));
        }

        // ⭐ 5. mode (как раньше)
        const modeArgs = [];
        const modeToUse = mode.length > 0 ? mode : defaultMode;
        modeToUse.forEach(m => modeArgs.push(String(m)));

        // ⭐ 6. Вызов opcode
        const allArgs = [
            ...paramArgs,
            ...modeArgs,
            ...inletBuses.map(String),
            ...outletBuses.map(String),
        ];
        const callLine = `${moduleName} ${allArgs.join(', ')}`;

        // ⭐ 7. Конвертеры для обычных кабелей (как раньше)
        const converterLines = [];
        for (const id of inputIds) {
            const cable = this._findCableForPort(instanceId, id, 'input');
            if (!cable) continue;
            const convKey = `${cable.id}_${id}`;
            const conv = this._converterBuses[convKey];
            if (!conv) continue;
            converterLines.push(`${conv.type} ${conv.sourceBus}, ${conv.bus}`);
        }

        // ⭐ 8. A2K для LED на Input (до callLine — сигнал уже в inletBuses)
        const tapA2KInputLines = [];
        for (const ind of leds) {
            const src = this._resolveIndicatorSource(panel, ind, inputIds, outputIds);
            if (!src || src.dir !== 'input') continue;
            const tap = taps.get(`input:${src.comp.id}`);
            if (!tap || tap.type !== 'audio' || tap.a2kBus === null) continue;
            if (!tapA2KInputLines.includes(`A2K ${tap.bus}, ${tap.a2kBus}`)) {
                tapA2KInputLines.push(`A2K ${tap.bus}, ${tap.a2kBus}`);
            }
        }

        // ⭐ 9. A2K для LED на Output (после callLine — opcode уже записал в tap.bus)
        const tapA2KOutputLines = [];
        for (const ind of leds) {
            const src = this._resolveIndicatorSource(panel, ind, inputIds, outputIds);
            if (!src || src.dir !== 'output') continue;
            const tap = taps.get(`output:${src.comp.id}`);
            if (!tap || tap.type !== 'audio' || tap.a2kBus === null) continue;
            if (!tapA2KOutputLines.includes(`A2K ${tap.bus}, ${tap.a2kBus}`)) {
                tapA2KOutputLines.push(`A2K ${tap.bus}, ${tap.a2kBus}`);
            }
        }

        // ⭐ 10. Строки LED
        const ledLines = [];
        for (const led of leds) {
            const src = this._resolveIndicatorSource(panel, led, inputIds, outputIds);
            if (!src) continue;
            const tap = taps.get(`${src.dir}:${src.comp.id}`);
            if (!tap) continue;

            let bus;
            if (tap.type === 'audio') {
                if (tap.a2kBus === null) continue;
                bus = tap.a2kBus;
            } else {
                bus = tap.bus;
            }

            const channelName = `led_${instanceName}_${instanceId}_${led.id}`;
            const ledType = led.ledType || 'rms';
            ledLines.push(`led_${ledType} ${bus}, "${channelName}"`);
        }

        // ⭐ 11. Строки MiniVU (только audio)
        const mvuLines = [];
        for (const mvu of mvus) {
            const src = this._resolveIndicatorSource(panel, mvu, inputIds, outputIds);
            if (!src) continue;
            const tap = taps.get(`${src.dir}:${src.comp.id}`);
            if (!tap) continue;

            if (tap.type !== 'audio') {
                console.warn(
                    `[CsoundGenerator] MiniVU id=${mvu.id} (module ${instanceName}/${instanceId}) ` +
                    `hangs on ${tap.type} ${src.dir}, MiniVU only supports audio — skipped`
                );
                continue;
            }

            const channelName = `mvu_${instanceName}_${instanceId}_${mvu.id}`;
            mvuLines.push(`mVU_rms ${tap.bus}, "${channelName}"`);
        }

        // ⭐ 12. Финальная сборка
        const result = [
            ...chngetLines,
            ...converterLines,
            ...tapA2KInputLines,
            callLine,
            ...tapA2KOutputLines,
            ...ledLines,
            ...mvuLines,
        ].join('\n');

        return result;
    }


    _parseVariants(udoText) {
        if (!udoText) return null;
        
        const lines = udoText.split('\n');
        const variants = [];
        let defaultSuffix = null;
        let strictMask = null;
        let pending = null;
        
        // ⭐ «Предварительные» теги — до ;@ ins
        let preSuffix = null;
        let preIsDefault = false;
        
        for (const line of lines) {
            const stripped = line.trim();
            
            // ;@ ins k k a k
            const mIns = stripped.match(/^;\s*@\s*ins\s+(.+)$/);
            if (mIns) {
                pending = {
                    ins: mIns[1].trim().split(/\s+/),
                    outs: null,
                    suffix: preSuffix,         // ⭐ подхватываем
                    opcodeName: null,
                    isDefault: preIsDefault,   // ⭐ подхватываем
                };
                if (preIsDefault && preSuffix) {
                    defaultSuffix = preSuffix;
                }
                // Сброс pre
                preSuffix = null;
                preIsDefault = false;
                continue;
            }
            
            // ;@ outs k
            const mOuts = stripped.match(/^;\s*@\s*outs\s+(.+)$/);
            if (mOuts && pending) {
                pending.outs = mOuts[1].trim().split(/\s+/);
                continue;
            }
            
            // ;@ variant k [default]
            const mVar = stripped.match(/^;\s*@\s*variant\s+(\S+)(?:\s+(default))?\s*$/);
            if (mVar) {
                const suffix = mVar[1];
                const isDefault = !!mVar[2];
                if (pending) {
                    pending.suffix = suffix;
                    pending.isDefault = isDefault;
                    if (isDefault) defaultSuffix = suffix;
                } else {
                    // ⭐ запоминаем до ;@ ins
                    preSuffix = suffix;
                    preIsDefault = isDefault;
                }
                continue;
            }
            
            // ;@ strict 0 0 1 0
            const mStrict = stripped.match(/^;\s*@\s*strict\s+(.+)$/);
            if (mStrict) {
                strictMask = mStrict[1].trim().split(/\s+/).map(x => parseInt(x) || 0);
                continue;
            }
            
            // opcode Foo_k, 0, kkkk
            const mOp = stripped.match(/^opcode\s+(\w+)\s*,/);
            if (mOp && pending) {
                pending.opcodeName = mOp[1];
                variants.push(pending);
                pending = null;
                continue;
            }
        }
        
        if (variants.length === 0) {
            return null;
        }
        
        if (!defaultSuffix && variants.length > 0) {
            defaultSuffix = variants[0].suffix || 'k';
        }
        
        if (!strictMask) {
            const n = variants[0]?.ins?.length || 0;
            strictMask = new Array(n).fill(0);
        }
        
        return {
            defaultSuffix,
            strict: strictMask,
            variants,
        };
    }


    _findCablesForOutput(moduleId, componentId) {
        const targetId = parseInt(componentId);
        const result = [];
        
        for (const cable of this._activeCables) {
            const jack = cable.fromJack;
            if (!jack) continue;
            
            let parentId = jack.parentModule?.jsonId || jack.parentModule?.moduleId;
            if (!parentId && jack.module) {
                parentId = jack.module.jsonId || jack.module.moduleId;
            }
            if (!parentId && jack.parent) {
                parentId = jack.parent.jsonId || jack.parent.moduleId;
            }
            
            if (parentId !== moduleId) continue;
            
            if (parseInt(jack.id) === targetId) {
                result.push(cable);
            }
        }
        
        return result;
    }

    getPanelById(instanceId) {
        if (this.system) {
            return this.system.components.find(
                c => c.jsonId === instanceId && c.constructor.name === 'Panel'
            );
        }
        return null;
    }

    async showFullCsd() {
        console.log('\n' + '='.repeat(60));
        console.log('🎵 FULL CSD FILE:');
        console.log('='.repeat(60));
        const csd = await this.generateFullCsd();
        console.log(csd);
        console.log('='.repeat(60) + '\n');
    }


    // В CsoundGenerator
    getLedChannelName(instanceName, instanceId, ledId) {
        return `led_${instanceName}_${instanceId}_${ledId}`;
    }
  
    log(message, style = 'normal') {
        const styles = {
            normal: 'color: #8a8a8a',
            dim: 'color: #666; font-style: italic',
            add: 'color: #8bc34a; font-weight: bold',
            remove: 'color: #ff6b6b; font-weight: bold'
        };
        //console.log(`%c[CsoundGenerator] ${message}`, styles[style] || styles.normal);
    }
    
    reset() {
        this.includes.clear();
        for (const udo of BASE_UDOS) this.includes.add(udo);
        this.modules.clear();
        this._activeCables = [];
        this._cableBusMap = {};
        this._audioBusCounter = 2;
        this._controlBusCounter = 2;
        this._audioBusCount = 2;
        this._controlBusCount = 2;
        this._scopeTables.clear();
        this._scopeTableCounter = 9000;
        this.log('🔄 Reset'); 
        //this.showFullCsd();
    }

    // ⭐ РЕГИСТРАЦИЯ ПОЛЬЗОВАТЕЛЬСКОГО МОДУЛЯ
    registerUserModule(name, data) {
        this.userModules[name] = data;
        //console.log(`📝 CsoundGenerator: registered user module "${name}"`);
    }


    // ⭐ ВСПОМОГАТЕЛЬНЫЕ МЕТОДЫ ДЛЯ ПАРСИНГА
    _extractDisplayName(code) {
        const match = code.match(/displayName:\s*['"]([^'"]+)['"]/);
        return match ? match[1] : null;
    }

    _extractGridHeight(code) {
        const match = code.match(/gridHeight:\s*(\d+)/);
        return match ? parseInt(match[1]) : null;
    }

    _extractInputs(code) {
        const match = code.match(/inputs:\s*\[([^\]]*)\]/);
        if (!match) return null;
        return match[1].split(',').map(s => parseInt(s.trim())).filter(n => !isNaN(n));
    }

    _extractOutputs(code) {
        const match = code.match(/outputs:\s*\[([^\]]*)\]/);
        if (!match) return null;
        return match[1].split(',').map(s => parseInt(s.trim())).filter(n => !isNaN(n));
    }

    /**
     * Выделить новую шину указанного типа и обновить счётчики.
     * @param {'audio'|'control'} type
     * @returns {number} номер шины
     */
    _allocateBus(type) {
        if (type === 'audio') {
            const bus = this._audioBusCounter++;
            this._audioBusCount = this._audioBusCounter;
            return bus;
        }
        const bus = this._controlBusCounter++;
        this._controlBusCount = this._controlBusCounter;
        return bus;
    }

    _normalizeJackType(jack) {
        const t = jack?.type || 'audio';
        if (t === 'audio' || t === 'logicAudio') return 'audio';
        if (t === 'control' || t === 'logic') return 'control';
        return 'audio';
    }

    /**
     * Найти компонент-источник для индикатора (LED/MiniVU) в панели.
     * Возвращает { comp, dir, index } или null.
     *  - dir = 'output' → index = позиция в outputIds
     *  - dir = 'input'  → index = позиция в inputIds
     */
    _resolveIndicatorSource(panel, indicator, inputIds, outputIds) {
        if (indicator.sourceComponentId === null || indicator.sourceComponentId === undefined) {
            return null;
        }
        const src = panel.components.find(
            c => String(c.id) === String(indicator.sourceComponentId)
        );
        if (!src) return null;

        const name = src.constructor.name;
        if (name === 'Output') {
            const idx = outputIds.indexOf(parseInt(src.id));
            if (idx === -1) return null;
            return { comp: src, dir: 'output', index: idx };
        }
        if (name === 'Input') {
            const idx = inputIds.indexOf(parseInt(src.id));
            if (idx === -1) return null;
            return { comp: src, dir: 'input', index: idx };
        }
        return null; // LED/MiniVU нельзя вешать на другие компоненты
    }


}
