// src/managers/UIManager.js
import { Panel } from '../components/Panel.js';

export class UIManager {
  constructor(system) {
    this.system = system;
    this.container = null;
    this.elements = {};
    this.isDragging = false;
    this.dragOffset = { x: 0, y: 0 };

    // Для кэширования значений
    this.lastValues = {
      modules: 0,
      cables: 0,
      fps: 0,
    };

    this.createUIContainer();
    this.makeDraggable();
    this.createCsoundControls();
    this.createZoomControls();
    this.createDebugInfo();

    // Запускаем периодическое обновление (вместо requestAnimationFrame)
    this.startPeriodicUpdates();
  }

  // === НОВЫЙ МЕТОД: запускает обновления раз в 200 мс ===
  startPeriodicUpdates() {
    setInterval(() => this.updateBasicInfoIfNeeded(), 500);
  }

  // === ОБНОВЛЕНИЕ БАЗОВОЙ ИНФОРМАЦИИ (FPS, модули, кабели) ===
  updateBasicInfoIfNeeded() {
    if (!this.elements.basicInfo || !this.system) return;

    const modules =
      this.system.components?.filter?.(
        (c) => c.constructor?.name === 'Panel' || c instanceof Panel,
      ).length || 0;

    const cables = this.system.patchManager?.cables?.length || 0;
    const fps = this.system.currentFPS || 0;

    if (
      this.lastValues.modules === modules &&
      this.lastValues.cables === cables &&
      this.lastValues.fps === fps
    ) {
      return;
    }

    this.lastValues.modules = modules;
    this.lastValues.cables = cables;
    this.lastValues.fps = fps;

    let fpsColor = '#6f6';
    if (fps < 30) fpsColor = '#f66';
    else if (fps < 50) fpsColor = '#ff6';

    const basicDiv = this.elements.basicInfo;
    if (!basicDiv._fpsSpan) {
      basicDiv.innerHTML = `
        <div style="display: flex; justify-content: space-between;">
          <span>🎯 FPS:</span>
          <span id="fpsValue" style="font-weight: bold;"></span>
        </div>
        <div style="display: flex; justify-content: space-between; margin-top: 4px;">
          <span>📦 Modules:</span>
          <span id="modulesValue" style="color: #0af;"></span>
        </div>
        <div style="display: flex; justify-content: space-between;">
          <span>🔌 Cables:</span>
          <span id="cablesValue" style="color: #f0f;"></span>
        </div>
      `;
      basicDiv._fpsSpan = basicDiv.querySelector('#fpsValue');
      basicDiv._modulesSpan = basicDiv.querySelector('#modulesValue');
      basicDiv._cablesSpan = basicDiv.querySelector('#cablesValue');
    }

    basicDiv._fpsSpan.textContent = fps;
    basicDiv._fpsSpan.style.color = fpsColor;
    basicDiv._modulesSpan.textContent = modules;
    basicDiv._cablesSpan.textContent = cables;
  }

  // === ПЕРЕТАСКИВАНИЕ ПАНЕЛИ (draggable) ===
  makeDraggable() {
    if (!this.container) return;

    const header = document.createElement('div');
    header.style.cssText = `
      height: 20px;
      background: #333;
      cursor: move;
      border-radius: 8px 8px 0 0;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 8px;
      color: #aaa;
      font-size: 11px;
      user-select: none;
      will-change: transform;
    `;

    // Название слева
    const headerTitle = document.createElement('span');
    headerTitle.textContent = '≡ Control Panel';
    header.appendChild(headerTitle);

    // Кнопка Design Settings справа
    const designBtn = document.createElement('button');
    designBtn.id = 'design-settings-btn';
    designBtn.innerHTML = '🎨';
    designBtn.title = 'Design Settings (D)';
    designBtn.style.cssText = `
      background: transparent;
      border: none;
      color: #0af;
      cursor: pointer;
      font-size: 13px;
      padding: 0 4px;
      line-height: 1;
      transition: transform 0.15s;
    `;
    designBtn.onmouseenter = () => {
      designBtn.style.transform = 'scale(1.2)';
    };
    designBtn.onmouseleave = () => {
      designBtn.style.transform = 'scale(1)';
    };
    designBtn.onmousedown = (e) => {
      // Не даём начать drag панели при клике на кнопку
      e.stopPropagation();
    };
    designBtn.onclick = (e) => {
      e.stopPropagation();
      this.system.designSettings?.toggle();
    };
    header.appendChild(designBtn);

    this.container.insertBefore(header, this.container.firstChild);

    this.container.style.position = 'fixed';
    this.container.style.left = '0';
    this.container.style.top = '0';
    this.container.style.right = 'auto';
    this.container.style.willChange = 'transform';

    this.currentX = 10;
    this.currentY = 10;
    this.updatePositionTransform();

    header.addEventListener('mousedown', (e) => {
      this.isDragging = true;
      const rect = this.container.getBoundingClientRect();
      this.dragOffset.x = e.clientX - rect.left;
      this.dragOffset.y = e.clientY - rect.top;
      this.container.style.cursor = 'grabbing';
      e.preventDefault();
    });

    document.addEventListener('mousemove', (e) => {
      if (!this.isDragging) return;
      const newX = e.clientX - this.dragOffset.x;
      const newY = e.clientY - this.dragOffset.y;
      const maxX = window.innerWidth - this.container.offsetWidth;
      const maxY = window.innerHeight - this.container.offsetHeight;
      this.currentX = Math.max(0, Math.min(newX, maxX));
      this.currentY = Math.max(0, Math.min(newY, maxY));
      this.updatePositionTransform();
    });

    document.addEventListener('mouseup', () => {
      if (this.isDragging) {
        this.isDragging = false;
        this.container.style.cursor = '';
      }
    });
  }

  updatePositionTransform() {
    this.container.style.transform = `translate(${this.currentX}px, ${this.currentY}px)`;
  }

  // === СОЗДАНИЕ КОНТЕЙНЕРА ===
  createUIContainer() {
    this.container = document.createElement('div');
    this.container.id = 'modular-ui-panel';
    this.container.style.cssText = `
      position: fixed;
      left: 0;
      top: 0;
      width: 220px;
      background: rgba(30, 30, 30, 0.85);
      padding: 15px;
      border-radius: 8px;
      color: white;
      font-family: Arial, sans-serif;
      border: 1px solid #444;
      z-index: 1000;
      max-height: 90vh;
      overflow-y: auto;
      pointer-events: auto;
      box-shadow: 0 4px 20px rgba(0, 0, 0, 0.7);
      backdrop-filter: blur(5px);
      -webkit-backdrop-filter: blur(5px);
      will-change: transform;
    `;

    document.body.appendChild(this.container);
    this.updatePositionTransform();
  }

  setTransparency(alpha = 0.85) {
    if (this.container) {
      const r = 30,
        g = 30,
        b = 30;
      this.container.style.background = `rgba(${r}, ${g}, ${b}, ${alpha})`;
    }
  }

  // === ZOOM КОНТРОЛЫ ===
  createZoomControls() {
    const zoomContainer = document.createElement('div');
    zoomContainer.style.marginTop = '15px';

    zoomContainer.innerHTML = `
      <div style="margin-bottom: 5px;">Zoom:</div>
      <div style="display: flex; gap: 5px; margin-bottom: 5px;">
        <button id="zoomOutBtn" style="flex: 1; padding: 8px; background: #444; color: white; border: 1px solid #666; border-radius: 4px; cursor: pointer;">-</button>
        <button id="zoomResetBtn" style="flex: 1; padding: 8px; background: #444; color: white; border: 1px solid #666; border-radius: 4px; cursor: pointer;">100%</button>
        <button id="zoomInBtn" style="flex: 1; padding: 8px; background: #444; color: white; border: 1px solid #666; border-radius: 4px; cursor: pointer;">+</button>
      </div>
      <div id="zoomInfo" style="text-align: center; font-size: 12px; color: #aaa;">100%</div>
    `;

    zoomContainer.querySelector('#zoomOutBtn').onclick = () =>
      this.system.zoom(-0.2);
    zoomContainer.querySelector('#zoomResetBtn').onclick = () =>
      this.system.resetZoom();
    zoomContainer.querySelector('#zoomInBtn').onclick = () =>
      this.system.zoom(0.2);

    // ⭐ SHAKE ALL
    const shakeContainer = document.createElement('div');
    shakeContainer.style.marginTop = '8px';
    shakeContainer.innerHTML = `
      <button id="shakeAllBtn" style="
        width: 100%;
        padding: 8px;
        background: #444;
        color: #0af;
        border: 1px solid #666;
        border-radius: 4px;
        cursor: pointer;
        font-size: 12px;
        transition: all 0.15s;
      " title="Shake all cables">🌀 Shake All</button>
    `;
    shakeContainer.querySelector('#shakeAllBtn').onclick = () => {
      this.system.patchManager.shakeAllCables(80);
    };
    zoomContainer.appendChild(shakeContainer);


    this.container.appendChild(zoomContainer);
    this.elements.zoomInfo = zoomContainer.querySelector('#zoomInfo');
  }

  // === CSOUND КОНТРОЛЫ ===
  createCsoundControls() {
      const csoundContainer = document.createElement('div');
      csoundContainer.style.cssText = `
          margin-top: 15px;
          padding: 10px;
          background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
          border-radius: 8px;
          border: 1px solid #0af;
          box-shadow: 0 2px 8px rgba(0, 170, 255, 0.2);
      `;

      csoundContainer.innerHTML = `
          <div style="display: flex; align-items: center; margin-bottom: 8px;">
              <div style="color: #0af; font-weight: bold; font-size: 14px; flex: 1;">🎵 Csound</div>
              <div id="csoundStatus" style="font-size: 10px; background: #333; padding: 2px 6px; border-radius: 10px; color: #8f8;">IDLE</div>
          </div>
          
          <button id="csoundRunBtn" style="
              width: 100%; 
              padding: 10px; 
              background: linear-gradient(to bottom, #0a5, #083); 
              color: white; 
              border: none; 
              border-radius: 6px; 
              cursor: pointer; 
              font-weight: bold; 
              font-size: 13px;
              transition: all 0.15s;
          ">
              ▶ Run
          </button>
          
          <div style="margin-top: 10px; padding: 8px; background: #1a1a1a; border-radius: 4px;">
              <div style="display: flex; align-items: center; gap: 6px; font-size: 10px; color: #666;">
                  <span>MIDI</span>
                  <div id="midiIndicator" style="
                      width: 8px; 
                      height: 8px; 
                      border-radius: 50%; 
                      background: #333; 
                      transition: all 0.1s;
                  "></div>
                  <span id="midiLastNote" style="color: #0af; font-family: monospace; font-size: 10px;">—</span>
              </div>
          </div>
          
          <div style="margin-top: 10px; padding: 8px; background: #1a1a1a; border-radius: 4px;">
              <div style="display: flex; align-items: center; gap: 8px; font-size: 10px;">
                  <span style="color: #666;">Grid</span>
                  <button id="gridToggleBtn" style="
                      flex: 1;
                      padding: 4px 8px;
                      background: #2a2a2a;
                      border: 1px solid #444;
                      color: #0af;
                      border-radius: 3px;
                      cursor: pointer;
                      font-size: 10px;
                  ">ON</button>
              </div>
          </div>


          <div style="margin-top: 8px; font-size: 10px; color: #666; text-align: center; line-height: 1.3;">
              <div id="csoundInfo">Not initialized</div>
          </div>
      `;

      this.container.appendChild(csoundContainer);

      // Сохраняем ссылки
      this.elements.csoundStatus  = csoundContainer.querySelector('#csoundStatus');
      this.elements.csoundInfo    = csoundContainer.querySelector('#csoundInfo');
      this.elements.csoundRunBtn  = csoundContainer.querySelector('#csoundRunBtn');
      this.elements.midiIndicator = csoundContainer.querySelector('#midiIndicator');
      this.elements.midiLastNote  = csoundContainer.querySelector('#midiLastNote');

      // Логика кнопки Run/Stop
      this.elements.csoundRunBtn.onclick = async () => {
          const engine = this.system?.csoundEngine;
          if (!engine) return;
          
          if (engine.state === 'idle' || engine.state === 'error') {
              await engine.init();
          } else if (engine.state === 'running') {
              await engine.stop();
          }
      };

      this.elements.gridToggleBtn = csoundContainer.querySelector('#gridToggleBtn');

      this.elements.gridToggleBtn.onclick = () => {
          const system = this.system;
          system.showGrid = !system.showGrid;
          this.elements.gridToggleBtn.textContent = system.showGrid ? 'ON' : 'OFF';
          this.elements.gridToggleBtn.style.color = system.showGrid ? '#0af' : '#666';
          system.forceRedraw();
      };
  }

  // === ДЕБАГ ИНФОРМАЦИЯ ===
  createDebugInfo() {
      const container = document.createElement('div');
      container.style.cssText = `
        margin-top: 15px;
        padding: 10px;
        background: #222;
        border-radius: 4px;
        font-size: 11px;
        font-family: monospace;
      `;

      const title = document.createElement('div');
      title.textContent = '📊 SYSTEM INFO';
      title.style.cssText = `
        color: #0af;
        margin-bottom: 8px;
        padding-bottom: 4px;
        border-bottom: 1px solid #444;
      `;

      this.elements.basicInfo = document.createElement('div');
      this.elements.basicInfo.style.cssText = `
        background: #1a1a1a;
        padding: 6px;
        border-radius: 3px;
        font-weight: bold;
      `;

      container.appendChild(title);
      container.appendChild(this.elements.basicInfo);

      this.elements.debugInfo = container;
      this.container.appendChild(container);
  }
  // === ПРОСТЫЕ МЕТОДЫ ОБНОВЛЕНИЯ ===
  updateZoomInfo(scale) {
    if (this.elements.zoomInfo) {
      this.elements.zoomInfo.textContent = `${Math.round(scale * 100)}%`;
    }
  }

  // В UIManager.js, когда ошибка — показываем красный статус
  updateCsoundStatus(text, color = '#fff') {
      if (this.elements.csoundStatus) {
          this.elements.csoundStatus.textContent = text;
          this.elements.csoundStatus.style.color = color;
      }
  }

  updateCsoundInfo(text) {
    if (this.elements.csoundInfo) {
      this.elements.csoundInfo.textContent = text;
    }
  }


  updateCsoundRunButton(state) {
      const btn = this.elements.csoundRunBtn;
      if (!btn) return;
      
      if (state === 'idle') {
          btn.textContent = '▶ Run';
          btn.style.background = 'linear-gradient(to bottom, #0a5, #083)';
          btn.disabled = false;
      } else if (state === 'running') {
          btn.textContent = '■ Stop';
          btn.style.background = 'linear-gradient(to bottom, #a00, #800)';
          btn.disabled = false;
      } else if (state === 'initializing') {
          btn.textContent = '⏳ Starting...';
          btn.style.background = 'linear-gradient(to bottom, #666, #444)';
          btn.disabled = true;
      } else if (state === 'error') {
          btn.textContent = '⟳ Retry';
          btn.style.background = 'linear-gradient(to bottom, #a00, #800)';
          btn.disabled = false;
      }
  }


  updatePatchInfo(filename, moduleCount, cableCount) {
    if (this.elements.patchInfo) {
      this.elements.patchInfo.style.display = 'block';
      this.elements.patchInfo.innerHTML = `
        <strong>${filename}</strong><br>
        Modules: ${moduleCount}<br>
        Cables: ${cableCount}<br>
        Loaded successfully
      `;
    }
  }

  updateDebugInfo(text) {
    if (this.elements.debugInfo) {
      this.elements.debugInfo.innerHTML = text;
      this.elements.debugInfo.scrollTop = this.elements.debugInfo.scrollHeight;
    }
  }

  // === УВЕДОМЛЕНИЯ ===
  showNotification(message, duration = 2000) {
    const notification = document.createElement('div');
    notification.textContent = message;
    notification.style.cssText = `
      position: fixed;
      bottom: 20px;
      right: 20px;
      padding: 10px 15px;
      background: rgba(0, 170, 85, 0.9);
      color: white;
      border-radius: 4px;
      z-index: 2000;
      font-family: Arial, sans-serif;
      font-size: 14px;
      animation: fadeInOut ${duration}ms ease;
      will-change: opacity, transform;
    `;

    if (!document.querySelector('#notification-animation')) {
      const style = document.createElement('style');
      style.id = 'notification-animation';
      style.textContent = `
        @keyframes fadeInOut {
          0% { opacity: 0; transform: translateY(10px); }
          10% { opacity: 1; transform: translateY(0); }
          90% { opacity: 1; transform: translateY(0); }
          100% { opacity: 0; transform: translateY(10px); }
        }
      `;
      document.head.appendChild(style);
    }

    document.body.appendChild(notification);

    setTimeout(() => {
      if (notification.parentNode) {
        notification.parentNode.removeChild(notification);
      }
    }, duration);

    return notification;
  }
}
