import { localize } from '../utils/locale.js';
const t = (en, zh, ru) => localize({ en, zh, ru });

// One reusable guide for the whole application and each granular module.
export function installGranularGuide(system) {
    if (document.getElementById('granular-guide-open')) return;
    const style = document.createElement('style');
    style.textContent = `
      #granular-guide-open { position:fixed;right:16px;top:12px;z-index:9000;padding:9px 14px;background:#253847;color:#fff;border:1px solid #708b9f;border-radius:4px;cursor:pointer;font:inherit; }
      #granular-guide { box-sizing:border-box;margin:auto;width:min(680px,calc(100vw - 32px));max-height:85vh;overflow:auto;padding:24px;background:#25292d;color:#f2f4f6;border:1px solid #71818d;border-radius:6px;font:15px/1.65 system-ui,sans-serif; }
      #granular-guide::backdrop {background:rgba(0,0,0,.65)}
      #granular-guide h2 {margin:0 0 16px;font-size:24px} #granular-guide h3 {margin:22px 0 8px;font-size:18px}
      #granular-guide ol {padding-left:24px} #granular-guide p {margin:8px 0} #granular-guide li {margin:8px 0} #granular-guide summary {cursor:pointer;font-weight:600;padding:10px 0}
      #granular-guide button {padding:9px 14px;background:#344b5e;color:#fff;border:1px solid #8298a9;border-radius:4px;font:inherit;cursor:pointer}
      #granular-guide button:focus-visible,#granular-guide summary:focus-visible,#granular-guide-open:focus-visible {outline:3px solid #a9d9ff;outline-offset:3px}
      #granular-guide .guide-actions {display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}
      #granular-guide [role=status] {color:#ffe0a3}
    `;
    document.head.append(style);
    const open = document.createElement('button');
    open.id = 'granular-guide-open';
    open.textContent = t('Start here', '入门指南', 'Начать здесь');
    open.onclick = () => showGranularGuide(system);
    document.body.append(open);
}

export function showGranularGuide(system, moduleName = '') {
    document.getElementById('granular-guide')?.remove();
    const dialog = document.createElement('dialog');
    dialog.id = 'granular-guide';
    dialog.setAttribute('aria-labelledby','granular-guide-title');
    const add = (tag, text, parent = dialog) => { const el=document.createElement(tag);el.textContent=text;parent.append(el);return el; };
    add('h2', t('Your first sound', '从零开始，让它发声', 'Ваш первый звук')).id='granular-guide-title';
    add('p', t('A patch is a set of modules connected by cables. A source makes sound; Outs2 sends it to your speakers.', '一个“音色工程”由模块和连线组成。声源模块产生声音，Outs2 输出模块把声音送到扬声器。只有声源，没有连接到 Outs2，也听不到声音。', 'Патч — это модули, соединённые кабелями. Источник создаёт звук, а Outs2 выводит его на динамики.'));
    const steps=add('ol','');
    for(const text of [
        t('Load the starter below. It connects Grain Osc → Outs2; no WAV or microphone is needed.', '点击下方“加载发声示例”。它已经连好“颗粒振荡器 → Outs2”，不需要 WAV 文件或麦克风。', 'Загрузите пример ниже: Grain Osc → Outs2. Файл WAV и микрофон не нужны.'),
        t('Lower your speaker volume, then press ▶ in the bottom bar. Press ■ to stop.', '先调低扬声器音量，再点击底栏的 ▶ 开始播放；点击 ■ 停止。', 'Уменьшите громкость динамиков и нажмите ▶ на нижней панели. Кнопка ■ останавливает звук.'),
        t('Drag Pitch up/down to hear the note change. Then try Grain Size and Density, one at a time.', '按住“音高”旋钮上下拖动，听音高变化。再分别试“粒长”和“颗粒/秒”，一次只改一个参数。', 'Перетаскивайте регулятор высоты вверх/вниз. Затем попробуйте длительность и плотность гранул по одному.')
    ])add('li',text,steps);
    const actions=add('div','');actions.className='guide-actions';
    const load=add('button',t('Load starter patch','加载发声示例','Загрузить пример'),actions);
    const close=add('button',t('Close guide','关闭指南','Закрыть'),actions);close.onclick=()=>dialog.close();
    const status=add('p','');status.setAttribute('role','status');
    load.onclick=async()=>{
        if(system.locked){status.textContent=t('Unlock the patch first using the lock control in the bottom bar.','请先通过底栏的锁定按钮解锁工程。','Сначала разблокируйте патч кнопкой замка на нижней панели.');return;}
        if(system.components?.length && !confirm(t('Replace the current patch? Save your work first.','示例会替换当前工程。请先保存现有工程，是否继续？','Заменить текущий патч? Сначала сохраните свою работу.')))return;
        load.disabled=true;
        try{
            await system.csoundEngine?.stop();
            const response=await fetch('/patches/granular-demo.json');if(!response.ok)throw Error('demo');
            const patch=await response.json();
            patch.modules=patch.modules.filter(m=>m.name==='GrainOsc'||m.name==='Outs2');
            patch.modules.forEach(m=>{m.hpos=m.name==='GrainOsc'?2:17;m.vpos=4;});
            const osc=patch.modules.find(m=>m.name==='GrainOsc'),out=patch.modules.find(m=>m.name==='Outs2');
            patch.cables=[0,1].map(jack=>({from:{id:osc.id,jack,pin:'out'},to:{id:out.id,jack,pin:'in'},type:'out-in',area:'VOICE'}));
            patch.textpad='Grain Osc L/R -> Outs2 L/R';
            const result=await system.loadPatchFromJson(patch);
            if(result===false||result?.success===false)throw Error('load');
            dialog.close();system.showNotification(t('Starter connected. Press ▶ in the bottom bar to hear it.','发声示例已连接。点击底栏 ▶ 开始播放。','Пример подключён. Нажмите ▶ на нижней панели.'));
        }catch{status.textContent=t('Could not load the example. Check that the granular library is installed.','示例加载失败，请检查颗粒模块库是否已安装。','Не удалось загрузить пример. Проверьте установку библиотеки.');}
        finally{load.disabled=false;}
    };
    add('h3',t('Which module do I use?','三个模块怎么选？','Какой модуль выбрать?'));
    const sections = [
        ['GrainOsc',t('Grain Osc — sound without a file','颗粒振荡器：不用文件就能发声','Grain Osc — звук без файла'),t('Built-in wave: Waveform 0 sine, 1 triangle, 2 saw, 3 square; Pitch 0 = 220 Hz (A3). Connect L/R to Outs2. The optional dry input is unnecessary for your first sound. Phase warp bends the phase inside every cycle: 0 keeps the wave unchanged, higher values add overtones (a sine gains harmonics, saw and square change character). Phase jitter varies each grain’s starting phase and Pitch jitter detunes. Hold warp (under Advanced) freezes the current warp amount. Patches saved with an older Grain Osc keep their saved Position value, which now sets the warp amount.', '内置波形：“波形”0 正弦、1 三角、2 锯齿、3 方波；音高 0 = 220 Hz（A3）。左右输出接到 Outs2 即可，第一次使用不用连接“干声输入”。“相位扭曲”会在每个周期内弯曲相位：0 保持原波形，越大泛音越多（正弦会长出谐波，锯齿和方波的音色会变化）。“相位抖动”改变每个颗粒的起始相位，“音高抖动”带来失谐。“锁定扭曲”（在“进阶”区）会保持当前的扭曲量。旧版 Grain Osc 存下的“位置”值现在就是扭曲量，所以旧工程听起来可能略有不同。', 'Встроенная волна: «Форма волны» 0 синус, 1 треугольник, 2 пила, 3 меандр; высота 0 = 220 Гц (A3). Подключите Л/П к Outs2. Сухой вход необязателен. «Деформация фазы» изгибает фазу внутри каждого цикла: 0 оставляет волну без изменений, больше — добавляет обертоны (у синуса появляются гармоники, у пилы и меандра меняется характер). «Разброс фазы» меняет начальную фазу для каждой гранулы, «Разброс высоты» расстраивает тон. «Фикс. деформ.» (раздел «Далее») удерживает текущую величину. Значение «Позиция», сохранённое в старом Grain Osc, теперь задаёт деформацию, поэтому старые патчи могут звучать немного иначе.')],
        ['GrainSample',t('Grain Sample — play your WAV','颗粒采样：播放你的 WAV 文件','Grain Sample — ваш файл WAV'),t('Select a slot (1–8), right-click the module → Load WAV, then connect L/R to Outs2. Empty slots are silent. Sample position chooses a point in the file and Position jitter scatters it. Scan moves the position through the file by itself (percent of the file per second, negative = backwards); Hold position pauses the scan and ignores Position changes while on. Reload the WAV after refreshing the app.', '选择采样槽（1–8），右键模块 → 导入 WAV，再把左右输出接到 Outs2。空槽没有声音。“采样位置”决定读取文件的哪一段，“位置抖动”让它随机散开。“扫描”让位置自动在文件中移动（每秒走过文件的百分比，负数为倒走）；“锁定位置”开启后会暂停扫描并忽略位置变化。刷新应用后需重新导入文件。', 'Выберите слот 1–8, ПКМ по модулю → Загрузить WAV, затем Л/П → Outs2. Пустой слот молчит. Позиция выбирает участок файла, «Разброс поз.» рассеивает его. «Скан.» сам двигает позицию по файлу (% файла в секунду, минус — назад); фиксация останавливает скан и игнорирует изменения позиции. После обновления страницы загрузите файл снова.')],
        ['GrainFreeze',t('Grain Freeze — capture another module','颗粒冻结：抓取其他模块的声音','Grain Freeze — захват звука'),t('Connect Grain Osc L → Audio in, then L/R → Outs2. Leave Record on for a few seconds; select Freeze to stop recording and play the captured buffer. An empty frozen buffer is silent. Lookback selects older recorded audio, up to about 4 seconds back.', '先接“颗粒振荡器左输出 → 音频输入”，再把本模块左右输出接到 Outs2。保持“录入”几秒，然后切到“冻结”，就会停止录入并反复读取缓冲里的声音。空缓冲直接冻结不会发声。“回看位置”选择更早录入的声音，最多回看约 4 秒。', 'Подключите Grain Osc Л → аудиовход, затем Л/П → Outs2. Запишите несколько секунд и включите заморозку. Пустой замороженный буфер молчит. Позиция выбирает более раннюю запись, до ~4 с назад.')],
    ];
    for(const [name,title,body]of sections){const detail=add('details','');detail.open=name===moduleName;add('summary',title,detail);add('p',body,detail);}
    add('h3',t('Shared controls','为什么有相同的控制？','Общие регуляторы'));
    add('p',t('All three cut their source into short grains. Density is grains per second; Size is each grain’s duration. Pitch changes playback rate. Jitter adds random offsets; Spread widens the stereo image. Start with the defaults.', '三者都把各自的声源切成短小的“颗粒”，所以共享颗粒参数：颗粒/秒控制数量，粒长控制每颗粒持续时间，音高改变播放速率，抖动加入随机变化，声像扩展让声音分布到左右两边。初学时保持默认值即可。', 'Все три создают короткие гранулы. Плотность — гранул в секунду, длина — длительность гранулы, высота — скорость чтения. Разброс добавляет случайность, панорама распределяет звук между каналами. Начните с настроек по умолчанию.'));
    add('p',t('At most 64 grains play at once. If Grains/s × Size (in seconds) is above 64, extra grains are skipped and the cloud gets thinner than the knobs suggest. Each panel follows the order you will use it: sections 1 and 2 make the sound, 3 sets the stereo output, Advanced holds rarely needed controls.', '最多同时播放 64 个颗粒：当“颗粒/秒 × 粒长（秒）”超过 64 时，多出的颗粒会被跳过，听起来比旋钮显示的稀疏。面板按使用顺序排列：1、2 区决定声音，3 区决定立体声输出，“进阶”区放不常用的控制。', 'Одновременно звучит не более 64 гранул: если «гранул/с × длина (с)» больше 64, лишние гранулы пропускаются и облако получается реже, чем показывают регуляторы. Панель устроена по порядку работы: разделы 1 и 2 формируют звук, 3 — стереовыход, «Далее» — редко нужные регуляторы.'));
    add('p',t('Grain window shapes each grain’s fade in/out: Hann is rounded, Triangle has straight slopes. Click the selector arrows to choose. It is unrelated to an application window. The mix knob (Dry/wet on Freeze, Grain/dry mix on Osc and Sample) at maximum is fully granular; at 0 you only hear the optional dry input. Seed is an advanced repeatability control.', '“颗粒包络”决定每个颗粒如何淡入和淡出：汉宁窗是圆滑曲线，三角窗是直线斜坡。点击选择器的小箭头切换。“窗”是音频术语，与软件窗口无关。混合旋钮（冻结模块叫“干湿比”，其余叫“颗粒/干声比”）拉满是纯颗粒声，0 只输出干声输入；随机种子是复现随机效果的进阶参数。', 'Окно гранулы задаёт нарастание и затухание: Ханн — плавная кривая, треугольное — прямые склоны. Переключайте стрелками. Микс на максимуме — только гранулы, 0 — только сухой вход. Seed нужен для повторяемой случайности.'));
    add('h3',t('Build and save your own patch','自己添加、连线和保存','Собрать и сохранить патч'));
    add('p',t('Space opens the module menu. Drag from an output jack to an input jack and release. Both modules must be in the same Voice/FX layer. Drag knobs vertically; Ctrl+wheel zooms and Space+drag pans. Use Save/Load in the main menu to keep your patch; WAV files must be reimported.', '空格键打开模块菜单。按住输出插孔，拖到目标输入插孔后松开即可连线；两个模块必须位于同一 Voice/FX 层。旋钮上下拖动调节；Ctrl+滚轮缩放，空格+拖动画布平移。通过主菜单 Save/Load 保存或打开工程，WAV 文件需要另行保留和重新导入。', 'Пробел открывает меню модулей. Перетащите кабель с выхода на вход. Оба модуля должны быть в одном слое Voice/FX. Регуляторы меняются вертикально; Ctrl+колесо — масштаб, пробел+перетаскивание — панорама. Save/Load сохраняет патч; WAV загрузите отдельно.'));
    add('h3',t('No sound?','没有声音时按这个顺序检查','Нет звука?'));
    add('p',t('Press ▶, check speaker volume, connect both outputs to Outs2, keep Density and Level above zero and the mix knob at maximum. Load a WAV for Sample; record before freezing for Freeze. Ignore the small modulation jacks until you are ready.', '先看是否已按 ▶、扬声器是否有音量；再看左右输出是否接到 Outs2，颗粒/秒和输出电平是否大于 0，混合旋钮是否拉满。采样模块要先导入 WAV，冻结模块要先录入声音。旋钮旁的小插孔是调制输入，初学时可以全部留空。', 'Нажмите ▶, проверьте громкость и соединения с Outs2. Плотность и уровень должны быть выше нуля, микс — на максимуме. Для Sample загрузите WAV; для Freeze сначала запишите звук. Малые входы модуляции можно оставить пустыми.'));
    dialog.addEventListener('keydown', e => e.stopPropagation());
    document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();
}